mapper.select:
SELECT a.id, a.mold_id, m.mold_code, m.name AS mold_name, a.reason, a.status, a.applicant_name, a.approver_name, a.handler_name, a.approval_comment, a.handler_comment, a.created_at, a.approved_at, a.handled_at FROM mold_scrap_applications a LEFT JOIN molds m ON a.mold_id = m.id
AND a.mold_id = #{moldId}
AND a.status = #{status}
ORDER BY a.created_at DESC
